// debug_unresolved.rs - Debug why symbols are unresolved
// Generated by step4_bootstrap - Debug Unresolved Symbols

use serde_json;
use std::collections::HashMap;

fn main() {
    println!("🔍 Debugging unresolved symbols...");
    
    let symbol_map: HashMap<String, serde_json::Value> = 
        serde_json::from_str(&std::fs::read_to_string("symbol_map.json").unwrap()).unwrap();
    
    let unresolved = vec!["env::var", "target_os", "target_env", "conditional_expr"];
    
    for symbol in unresolved {
        println!("\n🔍 Analyzing: {}", symbol);
        
        // Check if it exists as a key
        if symbol_map.contains_key(symbol) {
            println!("  ✅ Found as symbol key");
        } else {
            println!("  ❌ NOT found as symbol key");
        }
        
        // Check if it appears in dependencies
        let mut dep_count = 0;
        let mut found_in_files = Vec::new();
        
        for (name, data) in &symbol_map {
            if let Some(deps) = data["dependencies"].as_array() {
                for dep in deps {
                    if let Some(dep_str) = dep.as_str() {
                        if dep_str == symbol {
                            dep_count += 1;
                            if let Some(file) = data["source_file"].as_str() {
                                if !found_in_files.contains(&file.to_string()) {
                                    found_in_files.push(file.to_string());
                                }
                            }
                        }
                    }
                }
            }
        }
        
        println!("  📊 Found in {} dependencies across {} files", dep_count, found_in_files.len());
        
        // Show where it's used
        for file in found_in_files.iter().take(3) {
            println!("    - {}", file);
        }
        
        // Analyze why it's not captured
        analyze_symbol_type(symbol);
    }
}

fn analyze_symbol_type(symbol: &str) {
    println!("  🔍 Analysis:");
    
    match symbol {
        "env::var" => {
            println!("    - Qualified path: module::function");
            println!("    - Should resolve to 'var' function in env.rs");
            println!("    - Issue: Path resolution logic needs qualified matching");
        },
        "target_os" | "target_env" | "target_arch" | "target_vendor" => {
            println!("    - Compiler cfg attribute");
            println!("    - Not a real symbol, but a compile-time constant");
            println!("    - Issue: These are cfg! macro expansions, not parseable symbols");
        },
        "conditional_expr" => {
            println!("    - AST expression type we created");
            println!("    - Not a real symbol, but an expression classification");
            println!("    - Issue: This is metadata, not a resolvable symbol");
        },
        _ => {
            println!("    - Unknown symbol type");
        }
    }
}
